window.trialMonths = (days) => { const d = Number(days) || 7; return d >= 56 && d % 30 === 0 ? d / 30 : d >= 56 && d % 28 === 0 ? d / 28 : null; };
window.trialLabel = (days, locale) => { const d = Number(days) || 7, m = window.trialMonths(d); if (locale === "ja") return m ? `${m}カ月` : `${d}日間`; if (locale === "zh-TW") return m ? `${m}個月` : `${d}天`; return m ? `${m}-month` : `${d}-day`; };
window.trialSpan = (days, locale) => { const d = Number(days) || 7, m = window.trialMonths(d); if (locale === "en") return m ? `${m} months` : `${d} days`; return window.trialLabel(d, locale); };
